#include <iostream>
#include <iterator>
#include <vector>
#include <algorithm>

int main() {
  std::vector<int> numbers;
  std::istream_iterator<int> int_it(std::cin), eof;

  //Efficiently reads integers from cin until end-of-file
  std::copy(int_it, eof, std::back_inserter(numbers));

  //Process the numbers (e.g., calculate the sum)
  if (!numbers.empty()){
      int sum = 0;
      for (int num : numbers){
          sum += num;
      }
      std::cout << "Sum: " << sum << std::endl;
  } else {
      std::cout << "No numbers entered." << std::endl;
  }
  return 0;
}
